const Ctx=createContext<ContextType>(null!);const useCRM=()=>useContext(Ctx);
const nav=[{page:'operations',label:'Operações',icon:BriefcaseBusiness},{page:'dashboard',label:'Visão geral',icon:LayoutDashboard},{page:'pipeline',label:'Pipeline de vendas',icon:Columns3},{page:'leads',label:'Leads',icon:Users},{page:'inbox',label:'Conversas',icon:MessagesSquare},{page:'agenda',label:'Agenda',icon:CalendarDays},{page:'tasks',label:'Tarefas',icon:CheckSquare},{page:'finance',label:'Financeiro',icon:Wallet},{page:'experiments',label:'Testes A/B',icon:BarChart3},{page:'funnels',label:'Origens e funis',icon:Target},{page:'automations',label:'Automações',icon:Zap},{page:'integrations',label:'Integrações',icon:Link2},{page:'team',label:'Equipe',icon:Users},{page:'admin',label:'Administração',icon:Settings2},{page:'appearance',label:'Aparência e sons',icon:Sparkles}] as const;
